SELECT t1.question_id, t1.question_score, t1.question_difficulty, t1.question_type, t1.question_title, t1.create_time, t2.subject_name AS subject, t2.grade FROM ms_question t1 INNER JOIN ms_subjects t2 ON t1.subject_id = t2.subject_id WHERE t1.del_flag = 0
AND t1.question_id = #{questionId}
AND t1.subject_id = #{subjectId}
AND t2.grade = #{grade}
AND t1.question_type = #{questionType}
ORDER BY t1.create_time DESC

SELECT knowledge_id
FROM ms_knowledge_question
WHERE question_id = #{questionId}
